package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.*;import com.jnapanam.sportszone.notification.service.NotificationProviderSettingsService;import java.util.Properties;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSenderImpl;import org.springframework.stereotype.Component;
@Component public class SmtpEmailNotificationProvider implements NotificationProvider{private final NotificationProviderSettingsService settings;private final String host,user,password,from;private final int port;private final boolean auth,starttls;public SmtpEmailNotificationProvider(NotificationProviderSettingsService settings,@Value("${spring.mail.host:localhost}")String host,@Value("${spring.mail.port:587}")int port,@Value("${spring.mail.username:}")String user,@Value("${spring.mail.password:}")String password,@Value("${app.notification.email.from:}")String from,@Value("${spring.mail.properties.mail.smtp.auth:true}")boolean auth,@Value("${spring.mail.properties.mail.smtp.starttls.enable:true}")boolean starttls){this.settings=settings;this.host=host;this.port=port;this.user=user;this.password=password;this.from=from;this.auth=auth;this.starttls=starttls;}public NotificationChannel channel(){return NotificationChannel.EMAIL;}public String name(){return "smtp";}public String send(Notification n){String to=n.getUser().getEmail();if(to==null||to.isBlank())throw new IllegalStateException("User email is missing");JavaMailSenderImpl mail=new JavaMailSenderImpl();mail.setHost(settings.value("SMTP_HOST",host));mail.setPort(Integer.parseInt(settings.value("SMTP_PORT",String.valueOf(port))));mail.setUsername(settings.value("SMTP_USERNAME",user));mail.setPassword(settings.value("SMTP_PASSWORD",password));Properties p=mail.getJavaMailProperties();p.put("mail.smtp.auth",String.valueOf(auth));p.put("mail.smtp.starttls.enable",String.valueOf(starttls));SimpleMailMessage m=new SimpleMailMessage();String activeFrom=settings.value("SMTP_FROM",from);if(activeFrom!=null&&!activeFrom.isBlank())m.setFrom(activeFrom);m.setTo(to);m.setSubject(n.getSubject()==null?"Jnapanam Sports Zone":n.getSubject());m.setText(n.getMessage());mail.send(m);return "smtp-"+n.getId();}}
